import { ref, reactive, watch } from 'vue';
export default {
  props: {
    loading: Boolean,
    serverErrors: {
      type: Object,
      default: () => ({})
    }
  },
  emits: ['register'],
  setup(props, {
    emit
  }) {
    const username = ref('');
    const email = ref('');
    const password = ref('');
    const password2 = ref('');
    const formErrors = reactive({
      username: [],
      email: [],
      password: [],
      password2: [],
      general: null
    });
    watch(() => props.serverErrors, newErrors => {
      if (typeof newErrors === 'object') {
        Object.keys(formErrors).forEach(key => {
          formErrors[key] = Array.isArray(newErrors[key]) ? newErrors[key] : [newErrors[key]];
        });
      } else {
        formErrors.general = newErrors.general;
      }
    }, {
      deep: true
    });
    const clearError = field => {
      formErrors[field] = [];
      formErrors.general = null;
    };
    const submitForm = () => {
      emit('register', {
        username: username.value,
        email: email.value,
        password: password.value,
        password2: password2.value
      });
    };
    return {
      username,
      email,
      password,
      password2,
      formErrors,
      submitForm,
      clearError
    };
  }
};
